package fraymus.workspace;

import org.json.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;

/** Durable map/image records and one thread-owned native world, isolated from other app worlds. */
final class MapStore implements AutoCloseable {
    private final Path file,nativeDir;private final LinkedHashMap<String,JSONObject> references=new LinkedHashMap<>(),maps=new LinkedHashMap<>(),runs=new LinkedHashMap<>();
    private final ExecutorService worker=Executors.newSingleThreadExecutor(r->{var t=new Thread(r,"map-native-owner");t.setDaemon(true);return t;});
    private volatile boolean stop,closed;private volatile double inputX,inputZ;private volatile long inputUntil;private String active="";private JSONObject current;
    MapStore(Path project) throws Exception {file=project.resolve("maps/state.json");nativeDir=project.resolve("native");if(Files.exists(file)){var data=new JSONObject(Files.readString(file));for(Object raw:data.getJSONArray("references")){var o=(JSONObject)raw;MapDefinition.rules(o);references.put(o.getString("id"),o);}for(Object raw:data.getJSONArray("maps")){var o=(JSONObject)raw;intact(o);maps.put(o.getString("id"),o);}for(Object raw:data.getJSONArray("runs")){var o=(JSONObject)raw;if(o.getString("status").equals("running"))o.put("status","interrupted").put("reason","Process ended; a new native attempt starts from the immutable map");runs.put(o.getString("id"),o);}persist();}}
    private static JSONObject copy(JSONObject o){return new JSONObject(o.toString());}
    private static void intact(JSONObject o){if(!MeasurementStore.hash(o.getJSONObject("definition").toString()).equals(o.getString("sha256")))throw new IllegalStateException("Map source/compiled definition changed");MapTopology.verify(o.getJSONObject("definition"));}
    private synchronized void persist() throws Exception {Files.createDirectories(file.getParent());var pending=file.resolveSibling("state.pending.json");Files.writeString(pending,new JSONObject().put("references",new JSONArray(references.values())).put("maps",new JSONArray(maps.values())).put("runs",new JSONArray(runs.values())).toString(),StandardCharsets.UTF_8);try{Files.move(pending,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(pending,file,StandardCopyOption.REPLACE_EXISTING);}}
    synchronized JSONObject importImage(JSONObject input) throws Exception {if(references.size()>=32)throw new IllegalStateException("Reference history limit32 reached");var source=MapDefinition.image(input);references.put(source.getString("id"),source);persist();return copy(source);}
    synchronized JSONObject reference(String id){var source=references.get(id);if(source==null)throw new IllegalArgumentException("Unknown map reference");MapDefinition.rules(source);return copy(source);}
    synchronized JSONObject list(){return new JSONObject().put("references",new JSONArray(references.values().stream().map(o->new JSONObject().put("id",o.getString("id")).put("title",o.getString("title")).put("imageSha256",o.getString("imageSha256"))).toList())).put("maps",new JSONArray(maps.values().stream().map(o->new JSONObject().put("id",o.getString("id")).put("title",o.getString("title")).put("passed",o.getJSONObject("definition").getJSONObject("generation").getBoolean("passed"))).toList())).put("runs",new JSONArray(runs.values().stream().map(o->new JSONObject().put("id",o.getString("id")).put("mapId",o.getString("mapId")).put("status",o.getString("status"))).toList()));}
    synchronized JSONObject read(String id){var map=maps.get(id);if(map==null)throw new IllegalArgumentException("Unknown compiled map");intact(map);return copy(map);}
    synchronized JSONObject binding(String id){var map=read(id);return new JSONObject().put("id",id).put("sha256",map.getString("sha256"));}
    JSONObject build(String referenceId,JSONObject options) throws Exception {var source=reference(referenceId);var definition=MapDefinition.generated(source,options);if(Thread.currentThread().isInterrupted())throw new InterruptedException("Map generation cancelled before commit");return retain(definition,"Reference map · seed "+definition.getInt("seed"));}
    JSONObject fromProcedural(JSONObject goal,JSONArray layers) throws Exception {return retain(MapDefinition.layer(goal,layers),"Playable layer · "+goal.getString("title"));}
    private synchronized JSONObject retain(JSONObject definition,String title) throws Exception {if(closed||Thread.currentThread().isInterrupted())throw new InterruptedException("Map build stopped");if(maps.size()>=32)throw new IllegalStateException("Map history limit32 reached");String id=UUID.randomUUID().toString();var record=new JSONObject().put("id",id).put("title",title).put("createdAt",Instant.now()).put("definition",definition).put("sha256",MeasurementStore.hash(definition.toString()));maps.put(id,record);persist();return copy(record);}
    synchronized JSONObject run(String id){var r=runs.get(id);if(r==null)throw new IllegalArgumentException("Unknown map run");return copy(r);}
    synchronized JSONObject snapshot(){return current==null?new JSONObject().put("status","idle"):copy(current);}
    synchronized JSONObject start(String id,String mapId,boolean automatic,double disturbance,boolean realtime) throws Exception {
        if(closed||!active.isEmpty())throw new IllegalStateException("Stop the current map world first");if(runs.containsKey(id))return run(id);if(runs.size()>=64)throw new IllegalStateException("Map run history limit64 reached");RampDefinition.range(disturbance,-.5,.5,"disturbance impulseNs");var map=read(mapId);if(!map.getJSONObject("definition").getJSONObject("generation").getBoolean("passed"))throw new IllegalArgumentException("Unresolved map cannot become a playable scene");
        var r=new JSONObject().put("id",id).put("mapId",mapId).put("mapSha256",map.getString("sha256")).put("automatic",automatic).put("disturbanceNs",disturbance).put("status","running").put("createdAt",Instant.now()).put("samples",new JSONArray()).put("events",new JSONArray());runs.put(id,r);active=id;stop=false;inputX=0;inputZ=0;inputUntil=0;current=new JSONObject().put("id",id).put("mapId",mapId).put("status","running");persist();worker.submit(()->execute(id,map.getJSONObject("definition"),automatic,disturbance,realtime));return copy(r);
    }
    private void execute(String id,JSONObject definition,boolean automatic,double disturbance,boolean realtime){
        try(var world=new MapPhysics(definition,nativeDir)){long start=System.nanoTime();int settled=0;boolean impulse=false;while(world.tick<21600&&!stop&&!closed){if(automatic&&world.tick==480&&disturbance!=0){world.disturb(disturbance);impulse=true;synchronized(this){runs.get(id).getJSONArray("events").put(new JSONObject().put("kind","impulse").put("tick",world.tick).put("impulseNs",disturbance));}}boolean held=System.nanoTime()<inputUntil;world.step(automatic,held?inputX:0,held?inputZ:0);if(automatic&&world.pathIndex==definition.getJSONArray("path").length()-1&&world.error()<=.18&&world.avatar.getLinearVelocity().length()<=.18)settled++;else settled=0;
                if(world.tick%12==0||settled>=60){var s=world.sample();synchronized(this){runs.get(id).getJSONArray("samples").put(s);current=new JSONObject().put("id",id).put("mapId",runs.get(id).getString("mapId")).put("status","running").put("sample",s).put("automatic",automatic).put("speedMultiplier",realtime?(automatic?4:1):0);}if(settled>=60)break;}
                if(realtime){long wait=(long)(world.tick*BulletRamp.DT/(automatic?4:1)*1e9)-(System.nanoTime()-start);if(wait>0)Thread.sleep(Math.min(10,Math.max(1,wait/1_000_000)));}
            }
            synchronized(this){var r=runs.get(id);r.put("status",stop||closed?"stopped":"completed").put("final",world.sample()).put("impulseApplied",impulse);r.put("verification",verify(read(r.getString("mapId")),r));current.put("status",r.getString("status")).put("sample",r.getJSONObject("final")).put("verification",r.getJSONObject("verification"));persist();}
        }catch(Exception e){synchronized(this){var r=runs.get(id);r.put("status","interrupted").put("reason",String.valueOf(e.getMessage()));if(current!=null)current.put("status","interrupted").put("reason",String.valueOf(e.getMessage()));try{persist();}catch(Exception ignored){}}}finally{synchronized(this){active="";}}
    }
    synchronized JSONObject control(String id,double x,double z){if(!active.equals(id)||active.isEmpty()||runs.get(active).getBoolean("automatic"))throw new IllegalStateException("Start manual play first");RampDefinition.range(x,-1,1,"inputX");RampDefinition.range(z,-1,1,"inputZ");double norm=Math.max(1,Math.hypot(x,z));if(Math.abs(inputX-x/norm)+Math.abs(inputZ-z/norm)>.001&&runs.get(active).getJSONArray("events").length()<2000)runs.get(active).getJSONArray("events").put(new JSONObject().put("kind","manual-input").put("tick",current.optJSONObject("sample",new JSONObject()).optInt("tick",0)).put("x",x/norm).put("z",z/norm));inputX=x/norm;inputZ=z/norm;inputUntil=System.nanoTime()+400_000_000L;return new JSONObject().put("accepted",true).put("expiresMs",400);}
    synchronized JSONObject stop(){stop=true;inputX=0;inputZ=0;inputUntil=0;return snapshot();}
    static JSONObject verify(JSONObject record,JSONObject run){
        intact(record);if(!record.getString("sha256").equals(run.getString("mapSha256")))throw new IllegalStateException("Run/source binding changed");var m=record.getJSONObject("definition");var path=m.getJSONArray("path");int end=path.getInt(path.length()-1),w=m.getInt("width"),h=m.getInt("height");double size=m.getDouble("cellSizeM");var samples=run.getJSONArray("samples");int previous=0,blocked=0,wall=0,contacts=0;double distance=0,maxSpeed=0,forceMax=0;double[] before=null;
        for(Object raw:samples){var s=(JSONObject)raw;int tick=s.getInt("tick");if(s.getInt("positionAssignments")!=1)throw new IllegalStateException("Avatar position was assigned after spawn");if(tick<=previous||tick>21600)throw new IllegalStateException("Native trace tick order changed");previous=tick;var p=SpatialScene.vector(s.getJSONArray("position"),30);var v=SpatialScene.vector(s.getJSONArray("velocity"),30);double f=ObserverGeometry.norm(SpatialScene.vector(s.getJSONArray("force"),30));if(before!=null)distance+=ObserverGeometry.norm(ObserverGeometry.sub(p,before));before=p;int x=(int)Math.floor(p[0]/size+w/2.0),y=(int)Math.floor(p[2]/size+h/2.0);if(x<0||y<0||x>=w||y>=h||!m.getJSONArray("walkable").getBoolean(m.getJSONArray("cells").getInt(y*w+x)))blocked++;if(p[1]<.1||p[1]>.7)blocked++;wall+=s.getInt("wallContacts");contacts+=s.getInt("contacts");maxSpeed=Math.max(maxSpeed,ObserverGeometry.norm(v));forceMax=Math.max(forceMax,f);}
        var last=run.getJSONObject("final");var p=SpatialScene.vector(last.getJSONArray("position"),30);var target=MapDefinition.position(m,end,size);double error=Math.hypot(p[0]-target[0],p[2]-target[2]),speed=ObserverGeometry.norm(SpatialScene.vector(last.getJSONArray("velocity"),30));boolean passed=run.getString("status").equals("completed")&&run.getBoolean("automatic")&&samples.length()>10&&blocked==0&&error<=.2&&speed<=.2&&last.getInt("pathIndex")==path.length()-1&&forceMax<=24.0001;
        var result=new JSONObject().put("passed",passed).put("endpointErrorM",error).put("terminalSpeedMps",speed).put("blockedSamples",blocked).put("wallContacts",wall).put("contacts",contacts).put("travelM",distance).put("maxSpeedMps",maxSpeed).put("maxForceN",forceMax).put("effortNs",last.getDouble("effortNs")).put("samples",samples.length()).put("timeS",last.getDouble("timeS")).put("waypointsReached",last.getInt("pathIndex")+1).put("routeWaypoints",path.length()).put("nativePhysics",true).put("teleports",last.getInt("positionAssignments")-1).put("physicalAxes",3);if(m.has("topology"))result.put("topology",MapTopology.verify(m));return result;
    }
    synchronized String exportMap(String id){return new JSONObject().put("format","fraynix.playable-map").put("version",1).put("map",read(id)).toString();}
    synchronized JSONObject importMap(String text) throws Exception {if(text.getBytes(StandardCharsets.UTF_8).length>2_000_000)throw new IllegalArgumentException("Map package exceeds2MB");var pkg=new JSONObject(text);SpatialScene.keys(pkg,"format","version","map");if(!pkg.getString("format").equals("fraynix.playable-map")||pkg.getInt("version")!=1)throw new IllegalArgumentException("Unsupported playable-map package");var m=pkg.getJSONObject("map");intact(m);var d=m.getJSONObject("definition");JSONObject actual;
        if(d.getJSONObject("source").getString("kind").equals("reference-image")){var source=d.getJSONObject("source").getJSONObject("reference");var validated=MapDefinition.image(new JSONObject().put("pngBase64",source.getString("pngBase64")).put("tilePixels",source.getInt("tilePixels")).put("walkableColors",new JSONArray(java.util.stream.IntStream.range(0,source.getJSONArray("palette").length()).filter(i->source.getJSONArray("walkable").getBoolean(i)).mapToObj(i->source.getJSONArray("palette").getString(i)).toList())));validated.put("id",source.getString("id")).put("title",source.getString("title"));actual=MapDefinition.generated(validated,d.getJSONObject("options"));}
        else {var source=d.getJSONObject("source");var original=source.getJSONObject("original");if(!MeasurementStore.hash(original.toString()).equals(source.getString("sourceSha256")))throw new IllegalStateException("Original dungeon source hash differs");var fake=new JSONObject().put("status","completed").put("id",source.getString("goalId")).put("title","Imported original layer").put("proceduralDefinition",original.getJSONObject("definition")).put("proceduralResult",original).put("proceduralSha256",source.getString("sourceSha256")).put("proceduralCodeSha256",Procedural.codeIdentity());actual=MapDefinition.layer(fake,source.getJSONArray("layers"));actual.getJSONObject("source").put("selection",source.getString("selection"));}
        if(!actual.similar(d))throw new IllegalArgumentException("Imported map differs from independently reconstructed image/grid/colliders");return retain(actual,m.getString("title"));
    }
    @Override public void close(){closed=true;stop=true;worker.shutdownNow();try{worker.awaitTermination(3,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}}
}
